function t(
  topic: EuropeGuideTopic,
  sourceIds: string[],
  facts: NativeFacts,
): EuropeCountryProfile["topics"][EuropeGuideTopic] {
  return {
    sourceIds,
    copy: Object.fromEntries(
      locales.map((locale, index) => [locale, `${facts[index]} ${decisions[topic][index]}`]),
    ) as Record<EuropeBlogLocale, string>,
  };
}
